#[test]
fn surveyed_endpoint_propagation_references_load() {
    assert_eq!(PROPAGATION.len(), 6);
    for case in PROPAGATION {
        let _ = case.policy.boundary();
        for mesh in case.meshes {
            assert_eq!(mesh.averages.len(), mesh.cells);
            for cell in mesh.averages {
                for [lower, upper] in [[cell[0], cell[1]], [cell[2], cell[3]], [cell[4], cell[5]]] {
                    assert!(f64::from_bits(lower) <= f64::from_bits(upper));
                }
            }
        }
    }
}
